import React, { useState, useEffect } from "react";
import axios from "axios";
import { useLocation, useNavigate } from "react-router-dom";
import Navbar from "./Navbar";

function Register() {

  const location = useLocation();
  const navigate = useNavigate();

  const eventId = location.state?.eventId || "";
  const eventName = location.state?.eventName || "General Admission";

  const [formData, setFormData] = useState({
    name: "",
    college_name: "",
    phone: "",
    email: "",
    event_id: ""
  });

  const [registering, setRegistering] = useState(false);

  // Update event_id when page loads
  useEffect(() => {
    setFormData((prev) => ({
      ...prev,
      event_id: eventId
    }));
  }, [eventId]);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setRegistering(true);

    try {

      const res = await axios.post("http://localhost:5000/register", formData);

      if (res.data.success) {

        alert("Registration Successful! User ID: " + res.data.userId);

        // Navigate to QR page
        navigate("/qrcode", {
          state: {
            userId: res.data.userId,
            name: formData.name,
            eventName: eventName
          }
        });

      } else {
        alert(res.data.message);
      }

    } catch (error) {

      console.error("Submission Error:", error);

      alert("Registration failed. Check backend connection.");

    } finally {
      setRegistering(false);
    }
  };

  return (
    <div style={{ padding: "20px", textAlign: "center" }}>

      <Navbar />

      <h2>Event Registration</h2>

      <h3>Registering for: {eventName}</h3>

      <form onSubmit={handleSubmit} style={{ maxWidth: "400px", margin: "auto" }}>

        <input
          name="name"
          placeholder="Enter Name"
          onChange={handleChange}
          required
          style={inputStyle}
        />

        <input
          name="college_name"
          placeholder="College Name"
          onChange={handleChange}
          required
          style={inputStyle}
        />

        <input
          name="phone"
          placeholder="Phone Number"
          onChange={handleChange}
          required
          style={inputStyle}
        />

        <input
          name="email"
          placeholder="Email"
          onChange={handleChange}
          required
          style={inputStyle}
        />

        <button
          type="submit"
          disabled={registering}
          style={btnStyle}
        >
          {registering ? "Registering..." : "Register"}
        </button>

      </form>

    </div>
  );
}

const inputStyle = {
  display: "block",
  width: "100%",
  padding: "10px",
  margin: "10px 0"
};

const btnStyle = {
  padding: "10px 20px",
  backgroundColor: "#007bff",
  color: "white",
  border: "none",
  cursor: "pointer"
};

export default Register;
